      PROGRAM MSIS86QUERY
      DIMENSION D(8),T(2),AP(7)
      COMMON/UINR/IUMSIS,MONITO,IIEE
      IUMSIS=12
      MONITO=6
  100 READ(*,*,IOSTAT=IO) IYD,SEC,ALT,GLAT,GLONG,STL,F107A,F107,A
      IF(IO.NE.0) GOTO 200
      DO 110 J=1,7
  110 AP(J)=A
      CALL GTS5(IYD,SEC,ALT,GLAT,GLONG,STL,F107A,F107,AP,48,D,T)
      WRITE(*,'(10ES25.16E3)') D,T
      GOTO 100
  200 END
